// Run Context: this helper runs inside the Campaigns Manager, which hands it the run's launch shape.
// sd.launch.trigger      = the manager's trigger, 'schedule' or 'form'
// sd.launch.clientFilter = the manager's client scope (one Clients record id) or '' for every client
const sd=$getWorkflowStaticData('global');
const inp=($input.first()||{}).json||{};
sd.launch={ recordId:String(inp.recordId||''), trigger:String(inp.trigger||'schedule'), clientFilter:String(inp.clientFilter||''), startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];

// Init Run: one run shape from either door. Run Context set sd.launch (recordId '' on a schedule).
// A scheduled run serves every client; a launched run with a Client on its row serves that client only.
const sd=$getWorkflowStaticData('global');
const launch=sd.launch||{};
const clientFilter=String(launch.clientFilter||'').trim();
sd.run={ start:$now.toISO(), startMs:$now.toMillis(), trigger:launch.recordId?'form':'schedule', clientFilter, watermark:null, watermarkMs:0, watermarkMode:'' };
sd.clients={};
sd.currentClient='';
sd.pull=null;
sd.block=null;
return [{ json:{ trigger:sd.run.trigger, clientFilter } }];

// Set Watermark: the floor for "since the last run". This helper writes no rows of its own, so Get
// Watermark fetched the newest finished Campaigns Manager row (Succeeded or Succeeded with errors,
// no Client on the row: a run that served everyone). Its Run at, minus a 24 h overlap, is the floor;
// both writes this machine makes are idempotent, so the overlap costs nothing and covers clock skew.
// No such row (first run): the last 30 days. Leads are compared on their modified_at.
const sd=$getWorkflowStaticData('global');
const R=sd.run;
let wm=null, mode='';
try{
  const r=$input.first().json||{};
  const f=r.fields||r;
  const ra=f['Run at'];
  if(r.id&&ra){ const d=new Date(ra); if(!isNaN(d.getTime())){ wm=new Date(d.getTime()-24*3600*1000); mode='since the last manager run at '+ra+' (24 h overlap)'; } }
}catch(e){}
if(!wm){ wm=new Date(R.startMs-30*86400000); mode='first run: the last 30 days'; }
R.watermark=wm.toISOString();
R.watermarkMs=wm.getTime();
R.watermarkMode=mode;
return [{ json:{ watermark:R.watermark, mode } }];

// Map Clients: the client loop. Every Hub Clients row with a PlusVibe Workspace ID and a Clayroots
// Base ID (the search already filtered on both); a launched run with a Client on its row keeps that
// one only. The filter is applied here once, never deeper. An empty pick emits one placeholder so the
// Any Clients? gate routes straight to the run log (a loop node fed nothing never runs).
const sd=$getWorkflowStaticData('global');
const cf=String((sd.run||{}).clientFilter||'').trim();
const out=[];
for(const it of $input.all()){
  const r=it.json||{};
  const f=r.fields||r;
  const name=String(f['Client']||f['Client name']||'').trim();
  const ws=String(f['PlusVibe Workspace ID']||'').trim();
  const crBase=String(f['Clayroots Base ID']||'').trim();
  if(!r.id||!name||!ws||!crBase) continue;
  if(cf && r.id!==cf) continue;
  out.push({ json:{ clientRecId:r.id, clientName:name, ws, crBase } });
}
if(!out.length) return [{ json:{ _empty:true } }];
return out;

// Client Context: opens one client's slot in static data. Every counter the run-log line needs
// starts here; the leg nodes add to it; Close Client seals it.
const sd=$getWorkflowStaticData('global');
const c=$input.first().json;
sd.currentClient=c.clientRecId;
sd.pull=null;
sd.block=null;
sd.clients[c.clientRecId]={ name:c.clientName, ws:c.ws, crBase:c.crBase, dncTableId:'', dncTableName:'', leadsPulled:0, leadsRead:0, notInterested:0, unsubscribed:0, beforeWatermark:0, freeMail:0, noDomain:0, domains:{}, domainCount:0, blocked:0, alreadyBlocked:0, dncCreated:0, dncExisting:0, errors:[], warnings:[], skips:[] };
return [{ json:c }];

